{% extends "admin/admin_dashboard.html" %}
{% load static %}

{% block title %}Farm Management | CacaoGuard Admin{% endblock %}

{% block extra_css %}
<style>
    /* Modal Styling - Fixed positioning */
    .modal-overlay {
        position: fixed !important;
        top: 0 !important;
        left: 0 !important;
        right: 0 !important;
        bottom: 0 !important;
        background-color: rgba(0, 0, 0, 0.6) !important;
        display: none !important; /* Changed from flex to none by default */
        align-items: center !important;
        justify-content: center !important;
        z-index: 99999 !important;
        padding: 1rem !important;
    }
    
    .modal-overlay.show {
        display: flex !important; /* Only show when .show class is added */
    }

    .modal-content {
        background: white;
        border-radius: 0.5rem;
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
        max-height: calc(100vh - 2rem);
        overflow-y: auto;
        width: 100%;
        position: relative;
        margin: 0 auto;
    }

    #farm-modal .modal-content {
        max-width: 48rem;
    }

    #view-modal .modal-content {
        max-width: 56rem;
    }

    body.modal-open {
        overflow: hidden;
    }

    .form-input:focus {
        outline: none;
        border-color: #10b981;
        box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.1);
    }

    .btn-primary:hover {
        transform: translateY(-1px);
        box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
    }

    .leaflet-container {
        z-index: 1 !important;
    }

    .leaflet-popup {
        z-index: 3 !important;
    }

    .loading {
        display: inline-block;
        width: 20px;
        height: 20px;
        border: 3px solid #f3f3f3;
        border-top: 3px solid #3498db;
        border-radius: 50%;
        animation: spin 1s linear infinite;
    }

    @keyframes spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
    }

    .alert {
        padding: 0.75rem 1rem;
        margin-bottom: 1rem;
        border: 1px solid transparent;
        border-radius: 0.375rem;
    }

    .alert-success {
        color: #065f46;
        background-color: #d1fae5;
        border-color: #a7f3d0;
    }

    .alert-error {
        color: #991b1b;
        background-color: #fee2e2;
        border-color: #fecaca;
    }

    .pending-farm {
        background-color: #fef3c7;
        border-left: 4px solid #f59e0b;
    }

    .pending-badge {
        background-color: #f59e0b;
        color: white;
        padding: 0.25rem 0.5rem;
        border-radius: 0.25rem;
        font-size: 0.75rem;
        font-weight: 600;
    }

    .image-upload-container {
        border: 2px dashed #d1d5db;
        border-radius: 0.5rem;
        padding: 1rem;
        text-align: center;
        transition: border-color 0.2s;
        background-color: #f9fafb;
    }

    .image-upload-container:hover {
        border-color: #10b981;
        background-color: #f0fdf4;
    }

    .image-upload-container.dragover {
        border-color: #10b981;
        background-color: #dcfce7;
    }

    .image-preview-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
        gap: 0.5rem;
        margin-top: 1rem;
    }

    .image-preview-item {
        position: relative;
        border-radius: 0.5rem;
        overflow: hidden;
        border: 2px solid #e5e7eb;
    }

    .image-preview-item img {
        width: 100%;
        height: 80px;
        object-fit: cover;
    }

    .image-remove-btn {
        position: absolute;
        top: 0.25rem;
        right: 0.25rem;
        background: rgba(239, 68, 68, 0.9);
        color: white;
        border: none;
        border-radius: 50%;
        width: 20px;
        height: 20px;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        font-size: 0.75rem;
    }

    .image-remove-btn:hover {
        background: rgba(239, 68, 68, 1);
    }

    .image-gallery {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
        gap: 0.5rem;
    }

    .image-item {
        position: relative;
        cursor: pointer;
        border-radius: 0.5rem;
        overflow: hidden;
        transition: transform 0.2s;
    }

    .image-item:hover {
        transform: scale(1.05);
    }

    .image-overlay {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        background: linear-gradient(transparent, rgba(0,0,0,0.7));
        color: white;
        padding: 0.5rem;
        font-size: 0.75rem;
    }

    .file-input-wrapper {
        position: relative;
        overflow: hidden;
        display: inline-block;
        cursor: pointer;
        background: #10b981;
        color: white;
        padding: 0.5rem 1rem;
        border-radius: 0.375rem;
        transition: background-color 0.2s;
    }

    .file-input-wrapper:hover {
        background: #059669;
    }

    .file-input-wrapper input[type=file] {
        position: absolute;
        left: -9999px;
    }

    .notification {
        position: fixed;
        top: 1rem;
        right: 1rem;
        z-index: 9999;
        padding: 0.75rem 1.25rem;
        border-radius: 0.375rem;
        font-weight: 500;
        color: white;
    }

    .notification.success {
        background-color: #48bb78;
    }

    .notification.error {
        background-color: #e53e3e;
    }
</style>
{% endblock %}

{% block content %}
<div class="min-h-screen bg-gray-50">
    <!-- Header -->
  <!-- Header -->
<div class="bg-gradient-to-r from-green-600 via-emerald-600 to-teal-600 text-white py-6 mb-6">
    <div class="container mx-auto px-6">
        <div class="flex items-center">
            <div class="w-14 h-14 bg-white/20 rounded-xl flex items-center justify-center shadow-lg mr-4 animate-bounce">
                <i class="fas fa-tractor text-white text-2xl"></i>
            </div>
            <div>
                <h1 class="text-3xl font-bold mb-2">Farm Management System</h1>
                <p class="text-emerald-100">Manage cacao farms across Oriental Mindoro</p>
            </div>
        </div>
    </div>
</div>

    <!-- Alert Messages -->
    <div id="alert-container" class="container mx-auto px-6 mb-4"></div>

    <div class="container mx-auto px-6">
        <!-- Statistics Overview -->
        <div class="grid grid-cols-1 md:grid-cols-5 gap-6 mb-6">
            <div class="bg-white p-4 rounded-lg shadow-md border-l-4 border-green-500">
                <div class="flex items-center justify-between">
                    <div>
                        <h3 class="text-sm font-medium text-gray-600 uppercase">Total Farms</h3>
                        <p class="text-2xl font-bold text-green-600" id="total-farms">3</p>
                        <p class="text-xs text-gray-500">Active locations</p>
                    </div>
                    <i class="fas fa-map-marker-alt text-green-500 text-xl"></i>
                </div>
            </div>

            <div class="bg-white p-4 rounded-lg shadow-md border-l-4 border-blue-500">
                <div class="flex items-center justify-between">
                    <div>
                        <h3 class="text-sm font-medium text-gray-600 uppercase">Total Area</h3>
                        <p class="text-2xl font-bold text-blue-600" id="total-area">16.2</p>
                        <p class="text-xs text-gray-500">Hectares</p>
                    </div>
                    <i class="fas fa-expand-arrows-alt text-blue-500 text-xl"></i>
                </div>
            </div>

            <div class="bg-white p-4 rounded-lg shadow-md border-l-4 border-yellow-500">
                <div class="flex items-center justify-between">
                    <div>
                        <h3 class="text-sm font-medium text-gray-600 uppercase">Total Trees</h3>
                        <p class="text-2xl font-bold text-yellow-600" id="total-trees">1,800</p>
                        <p class="text-xs text-gray-500">Cacao trees</p>
                    </div>
                    <i class="fas fa-tree text-yellow-500 text-xl"></i>
                </div>
            </div>

            <div class="bg-white p-4 rounded-lg shadow-md border-l-4 border-purple-500">
                <div class="flex items-center justify-between">
                    <div>
                        <h3 class="text-sm font-medium text-gray-600 uppercase">Municipalities</h3>
                        <p class="text-2xl font-bold text-purple-600" id="total-municipalities">1</p>
                        <!-- <p class="text-xs text-gray-500">Victoria</p> -->
                    </div>
                    <i class="fas fa-city text-purple-500 text-xl"></i>
                </div>
            </div>

            <div class="bg-white p-4 rounded-lg shadow-md border-l-4 border-orange-500">
                <div class="flex items-center justify-between">
                    <div>
                        <h3 class="text-sm font-medium text-gray-600 uppercase">Pending</h3>
                        <p class="text-2xl font-bold text-orange-600" id="pending-requests">0</p>
                        <p class="text-xs text-gray-500">Awaiting approval</p>
                    </div>
                    <i class="fas fa-clock text-orange-500 text-xl"></i>
                </div>
            </div>
        </div>

        <!-- Main Management Section -->
        <div class="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-6">
            <!-- Map -->
            <div class="lg:col-span-3 bg-white p-6 rounded-lg shadow-md">
                <div class="flex justify-between items-center mb-4">
                    <h3 class="text-lg font-semibold">🗺️ Farm Locations Management</h3>
                    <div class="flex space-x-2">
                        <select id="municipality-filter" class="border rounded px-3 py-1 text-sm">
                            <option value="all">All Municipalities</option>
                            <option value="Baco">Baco</option>
                            <option value="Bansud">Bansud</option>
                            <option value="Bongabong">Bongabong</option>
                            <option value="Bulalacao">Bulalacao</option>
                            <option value="Calapan City">Calapan City</option>
                            <option value="Gloria">Gloria</option>
                            <option value="Mansalay">Mansalay</option>
                            <option value="Naujan">Naujan</option>
                            <option value="Pinamalayan">Pinamalayan</option>
                            <option value="Pola">Pola</option>
                            <option value="Puerto Galera">Puerto Galera</option>
                            <option value="Roxas">Roxas</option>
                            <option value="San Teodoro">San Teodoro</option>
                            <option value="Socorro">Socorro</option>
                            <option value="Victoria">Victoria</option>
                        </select>
                        <button id="refresh-map" class="bg-blue-500 text-white px-3 py-1 rounded text-sm hover:bg-blue-600">
                            <i class="fas fa-sync-alt"></i> Refresh
                        </button>
                    </div>
                </div>
                <div class="map-container">
                    <div id="admin-map" class="w-full h-96 rounded border"></div>
                </div>
            </div>

            <!-- Actions Panel -->
            <div class="bg-white p-6 rounded-lg shadow-md">
                <h3 class="text-lg font-semibold mb-4">⚡ Actions</h3>
                <div class="space-y-3">
                    <button onclick="openAddModal()" class="w-full bg-green-500 text-white py-2 px-4 rounded hover:bg-green-600 transition-colors text-sm">
                        <i class="fas fa-plus mr-2"></i>Add Farm
                    </button>
                    <button onclick="showPendingRequests()" class="w-full bg-orange-500 text-white py-2 px-4 rounded hover:bg-orange-600 transition-colors text-sm">
                        <i class="fas fa-clock mr-2"></i>Pending Requests <span id="pending-count" class="bg-white text-orange-500 px-2 py-1 rounded-full text-xs ml-1">0</span>
                    </button>
                    <button onclick="exportData()" class="w-full bg-blue-500 text-white py-2 px-4 rounded hover:bg-blue-600 transition-colors text-sm">
                        <i class="fas fa-download mr-2"></i>Export Data
                    </button>
                     <!-- Added print preview button under export CSV -->
                    <button onclick="printPreview()" class="w-full bg-green-500 text-white py-2 px-4 rounded hover:bg-green-600 transition-colors text-sm mt-2">
                        <i class="fas fa-print mr-2"></i>Print Preview
                    </button>
                </div>

                <!-- Status Summary -->
                <div class="mt-6">
                    <h4 class="font-semibold text-gray-700 mb-3 text-sm">Status Summary</h4>
                    <div class="space-y-2">
                        <div class="flex justify-between text-sm">
                            <span class="flex items-center">
                                <div class="w-2 h-2 bg-green-500 rounded-full mr-2"></div>
                                Active
                            </span>
                            <span id="status-active" class="font-medium">2</span>
                        </div>
                        <div class="flex justify-between text-sm">
                            <span class="flex items-center">
                                <div class="w-2 h-2 bg-yellow-500 rounded-full mr-2"></div>
                                Monitoring
                            </span>
                            <span id="status-monitoring" class="font-medium">1</span>
                        </div>
                        <div class="flex justify-between text-sm">
                            <span class="flex items-center">
                                <div class="w-2 h-2 bg-orange-500 rounded-full mr-2"></div>
                                Pending
                            </span>
                            <span id="status-pending" class="font-medium">0</span>
                        </div>
                        <div class="flex justify-between text-sm">
                            <span class="flex items-center">
                                <div class="w-2 h-2 bg-red-500 rounded-full mr-2"></div>
                                Attention
                            </span>
                            <span id="status-attention" class="font-medium">0</span>
                        </div>
                    </div>
                </div>

                <!-- Recent Activity -->
                <div class="mt-6">
                    <h4 class="font-semibold text-gray-700 mb-3 text-sm">Recent Updates</h4>
                    <div id="recent-activity" class="space-y-1 text-xs text-gray-600">
                        <div class="text-gray-600">• System initialized</div>
                        <div class="text-gray-600">• 3 farms loaded</div>
                        <div class="text-gray-600">• Ready for management</div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Farm Table -->
        <div class="bg-white p-6 rounded-lg shadow-md">
            <div class="flex justify-between items-center mb-4">
                <h3 class="text-lg font-semibold">📋 Farm Management</h3>
                <div class="flex space-x-2">
                    <input type="text" id="search-farms" placeholder="Search farms..."
                           class="border rounded px-3 py-2 text-sm w-64">
                    <button onclick="clearSearch()" class="bg-gray-500 text-white px-3 py-1 rounded text-sm hover:bg-gray-600">
                        <i class="fas fa-times"></i> Clear
                    </button>
                </div>
            </div>

            <div class="overflow-x-auto">
                <table class="min-w-full divide-y divide-gray-200">
                    <thead class="bg-gray-50">
                        <tr>
                            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Farm Name</th>
                            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Municipality</th>
                            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Area (Ha)</th>
                            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Trees</th>
                            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                        </tr>
                    </thead>
                    <tbody id="farms-table-body" class="bg-white divide-y divide-gray-200">
                        <!-- Populated by JavaScript -->
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Farm Cards Section -->
        <div class="bg-white p-6 rounded-lg shadow-md mt-6">
            <div class="flex justify-between items-center mb-4">
                <h3 class="text-lg font-semibold">🏡 Farm Cards View</h3>
                <div class="flex space-x-2">
                    <select id="card-status-filter" class="border rounded px-3 py-1 text-sm">
                        <option value="all">All Status</option>
                        <option value="Active">Active</option>
                        <option value="Monitoring">Monitoring</option>
                        <option value="Pending Approval">Pending</option>
                        <option value="Needs Attention">Needs Attention</option>
                    </select>
                    <button onclick="refreshCards()" class="bg-green-500 text-white px-3 py-1 rounded text-sm hover:bg-green-600">
                        <i class="fas fa-sync-alt"></i> Refresh
                    </button>
                </div>
            </div>

            <div id="admin-farms-grid" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                <!-- Populated by JavaScript -->
            </div>
        </div>
    </div>
</div>

<!-- View Details Modal -->
<div id="view-modal" class="modal-overlay">
    <div class="modal-content bg-white rounded-lg p-6 w-full max-w-4xl mx-auto max-h-[90vh] overflow-y-auto">
        <div class="flex justify-between items-center mb-4">
            <h2 id="view-modal-title" class="text-xl font-semibold">Farm Details</h2>
            <button onclick="closeViewModal()" class="text-gray-400 hover:text-gray-600 p-2">
                <i class="fas fa-times text-xl"></i>
            </button>
        </div>
        <div id="view-modal-content">
            <!-- Content populated by JavaScript -->
        </div>
    </div>
</div>

<!-- Add/Edit Modal - Fixed to not auto-open -->
<div id="farm-modal" class="modal-overlay">
    <div class="modal-content bg-white rounded-lg p-6 w-full max-w-4xl mx-auto max-h-[90vh] overflow-y-auto">
        <div class="flex justify-between items-center mb-4">
            <h2 id="modal-title" class="text-xl font-semibold">Add New Farm</h2>
            <button onclick="closeModal()" class="text-gray-400 hover:text-gray-600 p-2">
                <i class="fas fa-times text-xl"></i>
            </button>
        </div>

        <form id="farm-form" enctype="multipart/form-data">
            <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <!-- Left Column - Basic Information -->
                <div class="space-y-4">
                    <h3 class="text-lg font-semibold text-gray-800 border-b pb-2">Basic Information</h3>

                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-1">Farm Name *</label>
                        <input type="text" id="farm-name" name="name" required class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent">
                    </div>

                    <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Municipality *</label>
                            <select id="farm-municipality" name="municipality" required class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent">
                                <option value="">Select Municipality</option>
                                <option value="Baco">Baco</option>
                                <option value="Bansud">Bansud</option>
                                <option value="Bongabong">Bongabong</option>
                                <option value="Bulalacao">Bulalacao</option>
                                <option value="Calapan City">Calapan City</option>
                                <option value="Gloria">Gloria</option>
                                <option value="Mansalay">Mansalay</option>
                                <option value="Naujan">Naujan</option>
                                <option value="Pinamalayan">Pinamalayan</option>
                                <option value="Pola">Pola</option>
                                <option value="Puerto Galera">Puerto Galera</option>
                                <option value="Roxas">Roxas</option>
                                <option value="San Teodoro">San Teodoro</option>
                                <option value="Socorro">Socorro</option>
                                <option value="Victoria">Victoria</option>
                            </select>
                        </div>
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Barangay *</label>
                            <input type="text" id="farm-barangay" name="barangay" required class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent">
                        </div>
                    </div>

                    <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Area (Hectares)</label>
                            <input type="number" id="farm-area" name="area" step="0.1" min="0" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent">
                        </div>
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Number of Trees</label>
                            <input type="number" id="farm-trees" name="trees" min="0" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent">
                        </div>
                    </div>

                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-1">Status</label>
                        <select id="farm-status" name="status" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent">
                            <option value="Active">Active</option>
                            <option value="Monitoring">Monitoring</option>
                            <option value="Needs Attention">Needs Attention</option>
                        </select>
                    </div>

                    <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Latitude</label>
                            <input type="number" id="farm-lat" name="lat" step="any" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent" placeholder="e.g., 13.1375">
                        </div>
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Longitude</label>
                            <input type="number" id="farm-lng" name="lng" step="any" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent" placeholder="e.g., 121.2410">
                        </div>
                    </div>

                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-1">Description</label>
                        <textarea id="farm-description" name="description" rows="3" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent" placeholder="Enter farm description..."></textarea>
                    </div>

                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-1">Contact Information</label>
                        <input type="text" id="farm-contact" name="contact" class="form-input w-full border rounded px-3 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent" placeholder="Contact person or phone number">
                    </div>
                </div>

                <!-- Right Column - Image Upload -->
                <div class="space-y-4">
                    <h3 class="text-lg font-semibold text-gray-800 border-b pb-2">Farm Images</h3>

                    <!-- Image Upload Area -->
                    <div class="image-upload-container" id="image-upload-area">
                        <div class="text-center">
                            <i class="fas fa-cloud-upload-alt text-4xl text-gray-400 mb-4"></i>
                            <p class="text-gray-600 mb-2">Drag and drop images here or</p>
                            <div class="file-input-wrapper">
                                <input type="file" id="farm-images" name="images" multiple accept="image/*">
                                <span><i class="fas fa-plus mr-2"></i>Choose Images</span>
                            </div>
                            <p class="text-xs text-gray-500 mt-2">Supports: JPG, PNG, GIF (Max 5MB each)</p>
                        </div>
                    </div>

                    <!-- Image Preview Grid -->
                    <div id="image-preview-container" class="hidden">
                        <h4 class="text-sm font-medium text-gray-700 mb-2">Selected Images</h4>
                        <div id="image-preview-grid" class="image-preview-grid">
                            <!-- Preview images will be added here -->
                        </div>
                    </div>

                    <!-- Upload Progress -->
                    <div id="upload-progress" class="hidden">
                        <div class="bg-gray-200 rounded-full h-2">
                            <div id="upload-progress-bar" class="bg-green-500 h-2 rounded-full transition-all duration-300" style="width: 0%"></div>
                        </div>
                        <p class="text-sm text-gray-600 mt-1">Uploading images...</p>
                    </div>

                    <!-- Image Upload Tips -->
                    <div class="bg-blue-50 p-4 rounded-lg">
                        <h4 class="text-sm font-semibold text-blue-800 mb-2">📸 Image Upload Tips</h4>
                        <ul class="text-xs text-blue-700 space-y-1">
                            <li>• Upload clear photos of your cacao farm</li>
                            <li>• Include different angles and sections</li>
                            <li>• Show cacao trees, pods, and farming areas</li>
                            <li>• Maximum 10 images per farm</li>
                            <li>• Images help with farm verification</li>
                        </ul>
                    </div>
                </div>
            </div>

            <div class="flex justify-end space-x-3 mt-6 pt-4 border-t">
                <button type="button" onclick="closeModal()" class="px-6 py-2 text-gray-600 border rounded hover:bg-gray-50 transition-colors">
                    Cancel
                </button>
                <button type="submit" class="btn-primary px-6 py-2 bg-green-500 text-white rounded hover:bg-green-600 transition-colors">
                    <span id="save-btn-text"><i class="fas fa-save mr-2"></i>Save Farm</span>
                    <span id="save-btn-loading" style="display: none;"><span class="loading mr-2"></span>Saving...</span>
                </button>
            </div>
        </form>
    </div>
</div>

<!-- Include required libraries -->
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>

<script>
let adminMap;
let farmMarkers = [];
let farmsData = [];
let currentEditingFarm = null;
let selectedImages = [];

// Sample farms data - Oriental Mindoro
const SAMPLE_FARMS = [
    {
        id: 1,
        name: 'Barangay Poblacion Farm',
        municipality: 'Victoria',
        barangay: 'Poblacion',
        area: 4.5,
        trees: 15,
        status: 'Active',
        lat: 13.1375,
        lng: 121.2410,
        description: 'Primary cacao growing area with established farms',
        contact: 'Brgy. Captain Juan Santos',
        created_at: '2024-01-15',
        images: [
            '/static/images/download (2).jpg',
            '/static/images/download (1).jpg',
            '/static/images/download (3).jpg'
        ]
    },
    {
        id: 2,
        name: 'San Vicente Cacao Farm',
        municipality: 'Victoria',
        barangay: 'San Vicente',
        area: 3.2,
        trees: 10,
        status: 'Active',
        lat: 13.1500,
        lng: 121.2333,
        description: 'Emerging farming community with modern techniques',
        contact: 'Brgy. Captain Maria Cruz',
        created_at: '2024-01-14',
        images: [
            '/static/images/download (1).jpg',
            '/static/images/download.jpg'
        ]
    },
    {
        id: 3,
        name: 'Bethel Cacao Farm',
        municipality: 'Victoria',
        barangay: 'Bethel',
        area: 8.5,
        trees: 20,
        status: 'Monitoring',
        lat: 13.1440,
        lng: 121.2320,
        description: 'Large scale cacao production facility',
        contact: 'Farm Manager Pedro Reyes',
        created_at: '2024-01-13',
        images: [
            '/static/images/download (3).jpg',
            '/static/images/download (2).jpg'
        ]
    }
];

// Initialize the admin system
function initializeAdminSystem() {
    initializeMap();
    loadFarmsData();
    initializeImageUpload();
}

function initializeMap() {
    if (adminMap) adminMap.remove();
    adminMap = L.map('admin-map').setView([13.1375, 121.2410], 10);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
    }).addTo(adminMap);
}

function initializeImageUpload() {
    const uploadArea = document.getElementById('image-upload-area');
    const fileInput = document.getElementById('farm-images');

    // Drag and drop functionality
    uploadArea.addEventListener('dragover', function(e) {
        e.preventDefault();
        uploadArea.classList.add('dragover');
    });

    uploadArea.addEventListener('dragleave', function(e) {
        e.preventDefault();
        uploadArea.classList.remove('dragover');
    });

    uploadArea.addEventListener('drop', function(e) {
        e.preventDefault();
        uploadArea.classList.remove('dragover');

        const files = Array.from(e.dataTransfer.files).filter(file => file.type.startsWith('image/'));
        handleImageSelection(files);
    });

    // File input change
    fileInput.addEventListener('change', function(e) {
        const files = Array.from(e.target.files);
        handleImageSelection(files);
    });
}

function handleImageSelection(files) {
    if (files.length === 0) return;

    // Limit to 10 images
    if (selectedImages.length + files.length > 10) {
        showAlert('Maximum 10 images allowed per farm', 'error');
        return;
    }

    files.forEach(file => {
        if (file.size > 5 * 1024 * 1024) { // 5MB limit
            showAlert(`Image ${file.name} is too large. Maximum size is 5MB.`, 'error');
            return;
        }

        const reader = new FileReader();
        reader.onload = function(e) {
            const imageData = {
                file: file,
                url: e.target.result,
                name: file.name
            };

            selectedImages.push(imageData);
            updateImagePreview();
        };
        reader.readAsDataURL(file);
    });
}

function updateImagePreview() {
    const container = document.getElementById('image-preview-container');
    const grid = document.getElementById('image-preview-grid');

    if (selectedImages.length === 0) {
        container.classList.add('hidden');
        return;
    }

    container.classList.remove('hidden');
    grid.innerHTML = '';

    selectedImages.forEach((image, index) => {
        const previewItem = document.createElement('div');
        previewItem.className = 'image-preview-item';
        previewItem.innerHTML = `
            <img src="${image.url}" alt="${image.name}">
            <button type="button" class="image-remove-btn" onclick="removeImage(${index})">
                <i class="fas fa-times"></i>
            </button>
        `;
        grid.appendChild(previewItem);
    });
}

function removeImage(index) {
    selectedImages.splice(index, 1);
    updateImagePreview();
}

function showAlert(message, type = 'success') {
    const alertContainer = document.getElementById('alert-container');
    const alertClass = type === 'success' ? 'alert-success' : 'alert-error';
    const alertHtml = `
        <div class="alert ${alertClass}">
            <div class="flex justify-between items-center">
                <span>${message}</span>
                <button onclick="this.parentElement.parentElement.remove()" class="text-lg font-bold">&times;</button>
            </div>
        </div>
    `;
    alertContainer.innerHTML = alertHtml;
    // Auto-remove after 5 seconds
    setTimeout(() => {
        alertContainer.innerHTML = '';
    }, 5000);
}

async function loadFarmsData() {
    try {
        const response = await fetch('/api/admin/farms-firebase/');
        const data = await response.json();

        if (data.success) {
            farmsData = data.farms;
            updateStatistics();
            populateTable();
            updateMapMarkers();
            updateRecentActivity();
        } else {
            farmsData = SAMPLE_FARMS;
            updateStatistics();
            populateTable();
            updateMapMarkers();
            updateRecentActivity();
        }
    } catch (error) {
        console.error('Error loading farms data:', error);
        farmsData = SAMPLE_FARMS;
        updateStatistics();
        populateTable();
        updateMapMarkers();
        updateRecentActivity();
    }
}

function updateMapMarkers() {
    // Clear existing markers
    farmMarkers.forEach(marker => adminMap.removeLayer(marker));
    farmMarkers = [];

    farmsData.forEach(farm => {
        if (farm.lat && farm.lng) {
            const marker = L.marker([farm.lat, farm.lng]).addTo(adminMap);

            const mainImage = farm.images && farm.images.length > 0 ? farm.images[0] : '/static/images/default-farm.jpg';

            const popupContent = `
                <div class="p-3 min-w-[280px] ${farm.is_pending ? 'pending-farm' : ''}">
                    <img src="${mainImage}" alt="${farm.name}" class="w-full h-32 object-cover rounded mb-3 cursor-pointer"
                          onerror="this.style.display='none'" onclick="openImageModal('${mainImage}')">
                    <h3 class="font-semibold text-lg">${farm.name}</h3>
                    ${farm.is_pending ? '<span class="pending-badge">PENDING APPROVAL</span>' : ''}
                    <p class="text-sm text-gray-600 mb-2">${farm.municipality}, ${farm.barangay}</p>
                    <div class="space-y-1 text-sm">
                        <p><strong>Area:</strong> ${farm.area} hectares</p>
                        <p><strong>Trees:</strong> ${farm.trees.toLocaleString()}</p>
                        <p><strong>Status:</strong> <span class="px-2 py-1 rounded text-xs" style="background-color: ${getStatusColor(farm.status)}20; color: ${getStatusColor(farm.status)}">${farm.status}</span></p>
                        <p><strong>Contact:</strong> ${farm.contact}</p>
                        ${farm.user_name ? `<p><strong>Submitted by:</strong> ${farm.user_name}</p>` : ''}
                    </div>
                    <p class="text-sm text-gray-500 mt-2">${farm.description}</p>

                    ${farm.images && farm.images.length > 1 ? `
                        <div class="mt-3">
                            <p class="text-xs text-gray-500 mb-2">More Images (${farm.images.length})</p>
                            <div class="flex space-x-1 overflow-x-auto">
                                ${farm.images.slice(1, 4).map(img =>
                                     `<img src="${img}" alt="Farm" class="w-12 h-12 object-cover rounded cursor-pointer"
                                           onclick="openImageModal('${img}')" onerror="this.style.display='none'">`
                                ).join('')}
                                ${farm.images.length > 4 ? `<div class="w-12 h-12 bg-gray-200 rounded flex items-center justify-center text-xs">+${farm.images.length - 4}</div>` : ''}
                            </div>
                        </div>
                    ` : ''}

                    <div class="mt-3 space-x-2">
                        <button onclick="viewFarmDetails('${farm.id}')" class="text-blue-600 text-xs hover:text-blue-800">
                            <i class="fas fa-eye"></i> View
                        </button>
                        ${farm.is_pending ? `
                            <button onclick="approveFarmRequest('${farm.id.replace('pending_', '')}')" class="text-green-600 text-xs hover:text-green-800">
                                <i class="fas fa-check"></i> Approve
                            </button>
                            <button onclick="rejectFarmRequest('${farm.id.replace('pending_', '')}')" class="text-red-600 text-xs hover:text-red-800">
                                <i class="fas fa-times"></i> Reject
                            </button>
                        ` : `
                            <button onclick="editFarm('${farm.id}')" class="text-green-600 text-xs hover:text-green-800">
                                <i class="fas fa-edit"></i> Edit
                            </button>
                            <button onclick="deleteFarm('${farm.id}')" class="text-red-600 text-xs hover:text-red-800">
                                <i class="fas fa-trash"></i> Delete
                            </button>
                        `}
                        ${farm.images && farm.images.length > 1 ? `<button onclick="viewFarmImages(${farm.id})" class="text-purple-600 text-xs hover:text-purple-800">
                            <i class="fas fa-images"></i> Gallery
                        </button>` : ''}
                    </div>
                </div>
            `;

            marker.bindPopup(popupContent, { maxWidth: 320 });
            farmMarkers.push(marker);
        }
    });
}

function openImageModal(imageSrc) {
    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 bg-black bg-opacity-90 flex items-center justify-center z-[99999]';
    modal.onclick = (e) => {
        if (e.target === modal) document.body.removeChild(modal);
    };
    modal.innerHTML = `
        <div class="max-w-6xl max-h-full p-4 relative">
            <img src="${imageSrc}" alt="Farm Image" class="max-w-full max-h-full object-contain rounded-lg">
            <button onclick="document.body.removeChild(this.parentElement.parentElement)"
                     class="absolute top-4 right-4 text-white text-3xl hover:text-gray-300 bg-black bg-opacity-50 rounded-full w-12 h-12 flex items-center justify-center">
                <i class="fas fa-times"></i>
            </button>
        </div>
    `;
    document.body.appendChild(modal);
}

function viewFarmImages(farmId) {
    const farm = farmsData.find(f => f.id == farmId);
    if (!farm || !farm.images) return;

    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-[99999] p-4';
    modal.onclick = (e) => {
        if (e.target === modal) document.body.removeChild(modal);
    };

    const imageGallery = farm.images.map((img, index) =>
        `<img src="${img}" alt="Farm Image ${index + 1}" class="w-full h-48 object-cover rounded cursor-pointer hover:opacity-80" onclick="openImageModal('${img}')">`
    ).join('');

    modal.innerHTML = `
        <div class="bg-white rounded-lg p-6 max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div class="flex justify-between items-center mb-4">
                <h2 class="text-xl font-semibold">${farm.name} - Image Gallery</h2>
                <button onclick="document.body.removeChild(this.closest('.fixed'))" class="text-gray-400 hover:text-gray-600">
                    <i class="fas fa-times text-xl"></i>
                </button>
            </div>
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                ${imageGallery}
            </div>
        </div>
    `;
    document.body.appendChild(modal);
}

function viewFarmDetails(farmId) {
    const farm = farmsData.find(f => f.id == farmId);
    if (!farm) return;

    const modalContent = `
        <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div>
                <h3 class="text-lg font-semibold mb-3">Basic Information</h3>
                <div class="space-y-3 text-sm">
                    <div class="flex justify-between">
                        <span class="text-gray-600">Municipality:</span>
                        <span class="font-medium">${farm.municipality}</span>
                    </div>
                    <div class="flex justify-between">
                        <span class="text-gray-600">Barangay:</span>
                        <span class="font-medium">${farm.barangay}</span>
                    </div>
                    <div class="flex justify-between">
                        <span class="text-gray-600">Status:</span>
                        <span class="px-2 py-1 rounded text-xs font-medium" style="background-color: ${getStatusColor(farm.status)}20; color: ${getStatusColor(farm.status)}">
                            ${farm.status}
                        </span>
                    </div>
                    <div class="flex justify-between">
                        <span class="text-gray-600">Contact:</span>
                        <span class="font-medium">${farm.contact || 'N/A'}</span>
                    </div>
                    <div class="flex justify-between">
                        <span class="text-gray-600">Created:</span>
                        <span class="font-medium">${farm.created_at || 'N/A'}</span>
                    </div>
                    ${farm.user_name ? `
                        <div class="flex justify-between">
                            <span class="text-gray-600">Submitted by:</span>
                            <span class="font-medium">${farm.user_name}</span>
                        </div>
                    ` : ''}
                </div>

                <h3 class="text-lg font-semibold mt-6 mb-3">Farm Statistics</h3>
                <div class="grid grid-cols-2 gap-4">
                    <div class="bg-blue-50 p-3 rounded-lg text-center">
                        <div class="text-2xl font-bold text-blue-600">${farm.area}</div>
                        <div class="text-xs text-gray-600">Hectares</div>
                    </div>
                    <div class="bg-green-50 p-3 rounded-lg text-center">
                        <div class="text-2xl font-bold text-green-600">${farm.trees.toLocaleString()}</div>
                        <div class="text-xs text-gray-600">Trees</div>
                    </div>
                </div>

                <h3 class="text-lg font-semibold mt-6 mb-3">Description</h3>
                <p class="text-sm text-gray-600">${farm.description}</p>
            </div>

            <div>
                <h3 class="text-lg font-semibold mb-3">Farm Images</h3>
                <div class="image-gallery">
                    ${farm.images && farm.images.length > 0 ?
                        farm.images.map((img, index) =>
                            `<div class="image-item" onclick="openImageModal('${img}')">
                                <img src="${img}" alt="Farm Image ${index + 1}" class="w-full h-32 object-cover" onerror="this.style.display='none'">
                                <div class="image-overlay">Image ${index + 1}</div>
                            </div>`
                        ).join('') : '<p class="text-gray-500">No images available</p>'
                    }
                </div>

                <h3 class="text-lg font-semibold mt-6 mb-3">Location</h3>
                <div class="bg-gray-100 p-3 rounded-lg text-sm">
                    <div class="flex justify-between mb-2">
                        <span class="text-gray-600">Latitude:</span>
                        <span class="font-medium">${farm.lat}</span>
                    </div>
                    <div class="flex justify-between">
                        <span class="text-gray-600">Longitude:</span>
                        <span class="font-medium">${farm.lng}</span>
                    </div>
                </div>

                <div class="mt-6">
                    <h3 class="text-lg font-semibold mb-3">Quick Actions</h3>
                    <div class="space-y-2">
                        ${farm.is_pending ? `
                            <button onclick="approveFarmRequest('${farm.id.replace('pending_', '')}'); closeViewModal();" class="w-full bg-green-500 text-white py-2 px-4 rounded hover:bg-green-600 transition-colors text-sm">
                                <i class="fas fa-check mr-2"></i>Approve Farm Request
                            </button>
                            <button onclick="rejectFarmRequest('${farm.id.replace('pending_', '')}'); closeViewModal();" class="w-full bg-red-500 text-white py-2 px-4 rounded hover:bg-red-600 transition-colors text-sm">
                                <i class="fas fa-times mr-2"></i>Reject Request
                            </button>
                        ` : `
                            <button onclick="editFarm('${farm.id}'); closeViewModal();" class="w-full bg-green-500 text-white py-2 px-4 rounded hover:bg-green-600 transition-colors text-sm">
                                <i class="fas fa-edit mr-2"></i>Edit Farm
                            </button>
                            <button onclick="focusOnAdminFarm(${farm.lat}, ${farm.lng}); closeViewModal();" class="w-full bg-blue-500 text-white py-2 px-4 rounded hover:bg-blue-600 transition-colors text-sm">
                                <i class="fas fa-map-marker-alt mr-2"></i>View on Map
                            </button>
                            <button onclick="duplicateFarm('${farm.id}'); closeViewModal();" class="w-full bg-purple-500 text-white py-2 px-4 rounded hover:bg-purple-600 transition-colors text-sm">
                                <i class="fas fa-copy mr-2"></i>Duplicate Farm
                            </button>
                        `}
                    </div>
                </div>
            </div>
        </div>
    `;

    document.getElementById('view-modal-title').textContent = `${farm.name} - Details`;
    document.getElementById('view-modal-content').innerHTML = modalContent;
    document.body.classList.add('modal-open');
    document.getElementById('view-modal').classList.add('show');
}

function closeViewModal() {
    document.body.classList.remove('modal-open');
    document.getElementById('view-modal').classList.remove('show');
}

function updateStatistics() {
    const totalFarms = farmsData.length;
    const totalArea = farmsData.reduce((sum, farm) => sum + (farm.area || 0), 0);
    const totalTrees = farmsData.reduce((sum, farm) => sum + (farm.trees || 0), 0);
    const municipalities = [...new Set(farmsData.map(farm => farm.municipality))].length;

    // Status counts
    const activeFarms = farmsData.filter(f => f.status === 'Active').length;
    const monitoringFarms = farmsData.filter(f => f.status === 'Monitoring').length;
    const pendingFarms = farmsData.filter(f => f.status === 'Pending Approval').length;
    const attentionFarms = farmsData.filter(f => f.status === 'Needs Attention').length;

    document.getElementById('total-farms').textContent = totalFarms;
    document.getElementById('total-area').textContent = totalArea.toFixed(1);
    document.getElementById('total-trees').textContent = totalTrees.toLocaleString();
    document.getElementById('total-municipalities').textContent = municipalities;
    document.getElementById('pending-requests').textContent = pendingFarms;

    // Status summary
    document.getElementById('status-active').textContent = activeFarms;
    document.getElementById('status-monitoring').textContent = monitoringFarms;
    document.getElementById('status-pending').textContent = pendingFarms;
    document.getElementById('status-attention').textContent = attentionFarms;

    // Update pending count badge
    document.getElementById('pending-count').textContent = pendingFarms;

    // Populate cards
    populateAdminFarmsGrid();
}

function populateTable() {
    const tbody = document.getElementById('farms-table-body');
    tbody.innerHTML = '';

    farmsData.forEach(farm => {
        const row = document.createElement('tr');
        if (farm.is_pending) {
            row.className = 'pending-farm';
        }

        row.innerHTML = `
            <td class="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                ${farm.name}
                ${farm.is_pending ? '<span class="pending-badge ml-2">PENDING</span>' : ''}
            </td>
            <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">${farm.municipality}</td>
            <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-900">${farm.area || 'N/A'}</td>
            <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-900">${farm.trees || 'N/A'}</td>
            <td class="px-6 py-4 whitespace-nowrap">
                <span class="px-2 py-1 text-xs font-semibold rounded-full" style="background-color: ${getStatusColor(farm.status)}20; color: ${getStatusColor(farm.status)}">
                    ${farm.status}
                </span>
            </td>
            <td class="px-6 py-4 whitespace-nowrap text-sm font-medium space-x-2">
                <button onclick="viewFarmDetails('${farm.id}')" class="text-blue-600 hover:text-blue-900 p-1" title="View Details">
                    <i class="fas fa-eye"></i>
                </button>
                ${farm.is_pending ? `
                    <button onclick="approveFarmRequest('${farm.id.replace('pending_', '')}')" class="text-green-600 hover:text-green-900 p-1" title="Approve">
                        <i class="fas fa-check"></i>
                    </button>
                    <button onclick="rejectFarmRequest('${farm.id.replace('pending_', '')}')" class="text-red-600 hover:text-red-900 p-1" title="Reject">
                        <i class="fas fa-times"></i>
                    </button>
                ` : `
                    <button onclick="editFarm('${farm.id}')" class="text-green-600 hover:text-green-900 p-1" title="Edit">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button onclick="deleteFarm('${farm.id}')" class="text-red-600 hover:text-red-900 p-1" title="Delete">
                        <i class="fas fa-trash"></i>
                    </button>
                    <button onclick="duplicateFarm('${farm.id}')" class="text-purple-600 hover:text-purple-900 p-1" title="Duplicate">
                        <i class="fas fa-copy"></i>
                    </button>
                `}
            </td>
        `;
        tbody.appendChild(row);
    });
}

function populateAdminFarmsGrid() {
    const grid = document.getElementById('admin-farms-grid');
    grid.innerHTML = '';

    farmsData.forEach(farm => {
        const farmCard = document.createElement('div');
        farmCard.className = `bg-gray-50 p-4 rounded-lg border hover:shadow-md transition-shadow ${farm.is_pending ? 'pending-farm' : ''}`;

        const mainImage = farm.images && farm.images.length > 0 ? farm.images[0] : '/static/images/default-farm.jpg';

        farmCard.innerHTML = `
            <div class="mb-3">
                <img src="${mainImage}" alt="${farm.name}" class="w-full h-32 object-cover rounded cursor-pointer"
                      onerror="this.style.display='none'" onclick="openImageModal('${mainImage}')">
            </div>
            <div class="flex justify-between items-start mb-2">
                <h3 class="font-semibold text-gray-800">${farm.name}</h3>
                <span class="px-2 py-1 rounded text-xs font-medium" style="background-color: ${getStatusColor(farm.status)}20; color: ${getStatusColor(farm.status)}">
                    ${farm.status}
                </span>
            </div>
