            <p class="text-sm text-gray-600 mb-2">${farm.municipality}, ${farm.barangay}</p>
            <div class="space-y-1 text-sm text-gray-600">
                <p><i class="fas fa-expand-arrows-alt mr-2"></i>${farm.area} hectares</p>
                <p><i class="fas fa-tree mr-2"></i>${farm.trees.toLocaleString()} trees</p>
                <p><i class="fas fa-user mr-2"></i>${farm.contact}</p>
                ${farm.user_name ? `<p><i class="fas fa-user-plus mr-2"></i>By: ${farm.user_name}</p>` : ''}
            </div>
            <p class="text-sm text-gray-500 mt-2">${farm.description}</p>
            <div class="mt-3 flex justify-between items-center">
                <button onclick="focusOnAdminFarm(${farm.lat}, ${farm.lng})" class="text-blue-600 text-sm hover:text-blue-800">
