                        <i class="fas fa-eye"></i>
                    </button>
                    ${farm.is_pending ? `
                        <button onclick="approveFarmRequest('${farm.id.replace('pending_', '')}')" class="text-green-600 text-xs hover:text-green-800 p-1" title="Approve">
                            <i class="fas fa-check"></i>
                        </button>
                        <button onclick="rejectFarmRequest('${farm.id.replace('pending_', '')}')" class="text-red-600 text-xs hover:text-red-800 p-1" title="Reject">
                            <i class="fas fa-times"></i>
                        </button>
                    ` : `
                        <button onclick="editFarm('${farm.id}')" class="text-green-600 text-xs hover:text-green-800 p-1" title="Edit">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button onclick="deleteFarm('${farm.id}')" class="text-red-600 text-xs hover:text-red-800 p-1" title="Delete">
                            <i class="fas fa-trash"></i>
                        </button>
                    `}
                    ${farm.images && farm.images.length > 1 ? `<button onclick="viewFarmImages(${farm.id})" class="text-orange-600 text-xs hover:text-orange-800 p-1" title="Gallery">
                        <i class="fas fa-images"></i>
                    </button>` : ''}
                </div>
            </div>
        `;

        grid.appendChild(farmCard);
    });
}

function focusOnAdminFarm(lat, lng) {
    adminMap.setView([lat, lng], 15);
    // Find and open popup for this farm
    adminMap.eachLayer(function(layer) {
        if (layer instanceof L.Marker) {
            const markerLatLng = layer.getLatLng();
            if (Math.abs(markerLatLng.lat - lat) < 0.001 && Math.abs(markerLatLng.lng - lng) < 0.001) {
                layer.openPopup();
            }
        }
    });
}

function getStatusColor(status) {
    switch(status) {
        case 'Active': return '#10B981';
        case 'Monitoring': return '#F59E0B';
        case 'Pending Approval': return '#F97316';
        case 'Needs Attention': return '#EF4444';
        default: return '#6B7280';
    }
}

function updateRecentActivity() {
    const pendingCount = farmsData.filter(f => f.status === 'Pending Approval').length;
    const activities = [
        `${farmsData.length} farms loaded successfully`,
        pendingCount > 0 ? `${pendingCount} pending requests awaiting approval` : 'No pending requests',
        'System ready for management'
    ];

    const container = document.getElementById('recent-activity');
    container.innerHTML = activities.map(activity =>
        `<div class="text-gray-600">• ${activity}</div>`
    ).join('');
}

function showPendingRequests() {
    const pendingFarms = farmsData.filter(f => f.status === 'Pending Approval');

    if (pendingFarms.length === 0) {
        showAlert('No pending farm requests at this time.', 'success');
        return;
    }

    // Filter table to show only pending requests
    document.getElementById('search-farms').value = '';
    const tbody = document.getElementById('farms-table-body');
    tbody.innerHTML = '';

    pendingFarms.forEach(farm => {
        const row = document.createElement('tr');
        row.className = 'pending-farm';

        row.innerHTML = `
            <td class="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
