            <td class="px-6 py-4 whitespace-nowrap text-sm font-medium space-x-2">
                <button onclick="viewFarmDetails('${farm.id}')" class="text-blue-600 hover:text-blue-900 p-1" title="View Details">
                    <i class="fas fa-eye"></i>
