    currentEditingFarm = farmId;
    selectedImages = [];
    document.getElementById('modal-title').textContent = 'Edit Farm';

    // Populate form
    document.getElementById('farm-name').value = farm.name;
    document.getElementById('farm-municipality').value = farm.municipality;
    document.getElementById('farm-barangay').value = farm.barangay;
    document.getElementById('farm-area').value = farm.area || '';
    document.getElementById('farm-trees').value = farm.trees || '';
    document.getElementById('farm-status').value = farm.status;
    document.getElementById('farm-lat').value = farm.lat || '';
    document.getElementById('farm-lng').value = farm.lng || '';
    document.getElementById('farm-description').value = farm.description || '';
