async function deleteFarm(farmId) {
    if (!confirm('Are you sure you want to delete this farm? This action cannot be undone.')) return;

    try {
        const response = await fetch('/api/admin/farms-firebase/', {
            method: 'DELETE',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ id: farmId })
        });

        const data = await response.json();

        if (data.success) {
            // Remove from local data
            farmsData = farmsData.filter(f => f.id != farmId);
            updateStatistics();
            populateTable();
            updateMapMarkers();
            showAlert('Farm deleted successfully!');
        } else {
            showAlert('Error deleting farm: ' + data.error, 'error');
        }
    } catch (error) {
        console.error('Error deleting farm:', error);
        showAlert('Error deleting farm. Please try again.', 'error');
    }
}

async function saveFarm(formData) {
    const farmData = {
        name: formData.get('name'),
        municipality: formData.get('municipality'),
        barangay: formData.get('barangay'),
        area: parseFloat(formData.get('area')) || null,
        trees: parseInt(formData.get('trees')) || null,
        status: formData.get('status'),
        lat: parseFloat(formData.get('lat')) || null,
        lng: parseFloat(formData.get('lng')) || null,
        description: formData.get('description'),
        contact: formData.get('contact'),
        images: selectedImages.length > 0 ? selectedImages.map(img => img.url) : ['/static/images/download.jpg', '/static/images/download (1).jpg']
    };

    // Show loading state
    document.getElementById('save-btn-text').style.display = 'none';
    document.getElementById('save-btn-loading').style.display = 'inline';

    try {
        let response;

        if (currentEditingFarm) {
            // Update existing farm
            farmData.id = currentEditingFarm;
            response = await fetch('/api/admin/farms-firebase/', {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(farmData)
            });
        } else {
            // Add new farm
            response = await fetch('/api/admin/farms-firebase/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(farmData)
            });
        }

        const data = await response.json();

        if (data.success) {
            if (currentEditingFarm) {
                // Update existing farm in local data
                const index = farmsData.findIndex(f => f.id == currentEditingFarm);
                if (index !== -1) {
                    farmsData[index] = { ...farmsData[index], ...farmData };
                }
                showAlert('Farm updated successfully!');
            } else {
                // Add new farm to local data
                if (data.farm) {
                    farmsData.push(data.farm);
                }
                showAlert('Farm added successfully!');
            }

            updateStatistics();
            populateTable();
            updateMapMarkers();
            closeModal();
        } else {
            showAlert('Error saving farm: ' + data.error, 'error');
        }
    } catch (error) {
        console.error('Error saving farm:', error);
        showAlert('Error saving farm. Please try again.', 'error');
    } finally {
        // Hide loading state
        document.getElementById('save-btn-text').style.display = 'inline';
        document.getElementById('save-btn-loading').style.display = 'none';
    }
}

