                        </div>
                        <p class="text-sm text-gray-500 mt-2">${farm.description}</p>
                        <div class="mt-3 space-x-2">
                            <button onclick="viewFarmDetails('${farm.id}')" class="text-blue-600 text-xs hover:text-blue-800">
                                <i class="fas fa-eye"></i> View Details
                            </button>
                            ${farm.is_pending ? `
                                <button onclick="approveFarmRequest('${farm.id.replace('pending_', '')}')" class="text-green-600 text-xs hover:text-green-800">
                                    <i class="fas fa-check"></i> Approve
                                </button>
                                <button onclick="rejectFarmRequest('${farm.id.replace('pending_', '')}')" class="text-red-600 text-xs hover:text-red-800">
                                    <i class="fas fa-times"></i> Reject
                                </button>
                            ` : `
                                <button onclick="editFarm('${farm.id}')" class="text-green-600 text-xs hover:text-green-800">
                                    <i class="fas fa-edit"></i> Edit
                                </button>
                                <button onclick="deleteFarm('${farm.id}')" class="text-red-600 text-xs hover:text-red-800">
                                    <i class="fas fa-trash"></i> Delete
                                </button>
                            `}
