// Placeholder functions for missing functionality
async function approveFarmRequest(requestId) {
    if (!confirm('Are you sure you want to approve this farm request?')) return;
    
    try {
        const response = await fetch('/api/admin/approve-farm/', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': getCookie('csrftoken')
            },
            body: JSON.stringify({
                request_id: requestId
            })
        });
        
        const data = await response.json();
        
        if (data.success) {
            showAlert(data.message || 'Farm request approved successfully!', 'success');
            // Reload farms data
            loadAllFarms();
        } else {
            showAlert(data.error || 'Failed to approve farm request', 'error');
        }
    } catch (error) {
        showAlert('Error approving farm request: ' + error.message, 'error');
    }
}

async function rejectFarmRequest(requestId) {
    const reason = prompt('Please provide a reason for rejection:');
    if (!reason) return;
    
    try {
        const response = await fetch('/api/admin/reject-farm/', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': getCookie('csrftoken')
            },
            body: JSON.stringify({
                request_id: requestId,
                reason: reason
            })
        });
        
        const data = await response.json();
        
        if (data.success) {
            showAlert(data.message || 'Farm request rejected successfully!', 'success');
            // Reload farms data
            loadAllFarms();
        } else {
            showAlert(data.error || 'Failed to reject farm request', 'error');
        }
    } catch (error) {
        showAlert('Error rejecting farm request: ' + error.message, 'error');
    }
}

// Helper function to get CSRF token
function getCookie(name) {
    let cookieValue = null;
    if (document.cookie && document.cookie !== '') {
        const cookies = document.cookie.split(';');
        for (let i = 0; i < cookies.length; i++) {
            const cookie = cookies[i].trim();
            if (cookie.substring(0, name.length + 1) === (name + '=')) {
                cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
                break;
            }
        }
    }
    return cookieValue;
}
